/* ---------- P9o: staff (admins + moderators), verified Treesh Icons, bans, mutes, talents ---------- */
const MOD_DUR=[['1h','1 hour',36e5],['1d','1 day',864e5],['3d','3 days',2592e5],['7d','1 week',6048e5],['30d','30 days',2592e6],['perm','Permanent',0],['custom','Pick a date',-1]];
const MOD_ACT={ban:['ban','banned'],unban:['undo-2','lifted the ban on'],mute:['volume-x','muted'],unmute:['volume-2','unmuted'],edit:['user-pen','edited'],verify:['badge-check','verified'],unverify:['badge-x','removed verification from'],make_mod:['shield-plus','made a moderator:'],remove_mod:['shield-minus','removed moderator from'],make_admin:['shield-check','made an admin:'],remove_admin:['shield-off','removed admin from'],delete:['trash-2','deleted']};
const MOD_ROLES=[['user','Member','user-round','Regular account'],['moderator','Moderator','shield','Mute & edit profiles'],['admin','Admin','shield-check','Full staff powers']];
let _mod=null, _modD=null, _stT=0;
function stMe(){ return (sbUser()&&state._sxMe)||null; }
function stRole(){ const m=stMe(); return (m&&m.role)||'user'; }
function stStaff(){ return stRole()==='moderator'||stRole()==='admin'; }
function stMuted(){ const m=stMe(); return !!(m&&m.muted_until&&Date.parse(m.muted_until)>Date.now()); }
function stFmt(t){ const d=new Date(t); if(!t||isNaN(d)) return ''; if(d.getFullYear()>2100) return 'forever'; return d.toLocaleString(undefined,{month:'short',day:'numeric',year:d.getFullYear()!==new Date().getFullYear()?'numeric':undefined,hour:'numeric',minute:'2-digit'}); }
function stUntil(t){ const s=stFmt(t); return s==='forever'?'permanently':'until '+s; }
function stIcon(id){ return (id&&ARTIST_BY_ID[id])||null; }
