/* badges next to names */
function sxNameBadges(u,big,key){ if(!u) return ''; const k=key?'-'+key:''; let h=''; const ic=u.verified?stIcon(u.verified_icon):null;
  if(u.verified) h+=(big&&ic)?`<button type="button" data-act="artist-open" data-id="${esc(ic.id)}" class="sx-vf press" title="Verified Treesh Icon: ${esc(ic.name)}" aria-label="Verified Treesh Icon, open ${esc(ic.name)}" data-testid="badge-verified${k}"><i data-lucide="badge-check"></i></button>`:`<span class="sx-vf" title="${ic?'Verified Treesh Icon: '+esc(ic.name):'Verified'}" aria-label="Verified" data-testid="badge-verified${k}"><i data-lucide="badge-check"></i></span>`;
  if(u.role==='admin') h+=`<span class="sx-role is-admin" title="Treesh admin" data-testid="badge-admin${k}"><i data-lucide="shield-check"></i>${big?'<b>Admin</b>':''}</span>`;
  else if(u.role==='moderator') h+=`<span class="sx-role is-mod" title="Treesh moderator" data-testid="badge-moderator${k}"><i data-lucide="shield"></i>${big?'<b>Moderator</b>':''}</span>`;
  return h?`<span class="sx-nb${big?' is-big':''}">${h}</span>`:''; }
function sxIconChip(d){ const ic=d&&d.verified?stIcon(d.verified_icon):null; return ic?`<button type="button" data-act="artist-open" data-id="${esc(ic.id)}" class="sx-chip is-icon press" data-testid="uprof-icon-link"><i data-lucide="badge-check"></i>Treesh Icon \u00b7 ${esc(ic.name)}</button>`:''; }

/* public: top listening + friend list */
function sxListening(){ const pc=state.playCounts||{}, art={};
  const songs=Object.keys(pc).map(id=>[id,+pc[id]||0]).filter(x=>x[1]>0&&SONG_BY_ID[x[0]]).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([id,n])=>Object.assign(sxSong(SONG_BY_ID[id]),{n}));
  Object.keys(pc).forEach(id=>{ const s=SONG_BY_ID[id], n=+pc[id]||0; if(!s||!n) return; ((s.artistIds&&s.artistIds.length)?s.artistIds:['n:'+(s.artist||'')]).forEach(a=>{ art[a]=(art[a]||0)+n; }); });
  const artists=Object.keys(art).sort((a,b)=>art[b]-art[a]).slice(0,8).map(k=>{ const A=k.indexOf('n:')===0?null:ARTIST_BY_ID[k]; return {id:A?A.id:'',n:A?A.name:k.slice(2),img:A&&/^https?:/.test(A.image||'')?A.image:'',p:art[k]}; }).filter(a=>a.n);
  return {songs,artists}; }
const _sxSnap9o=sxSnapshot; sxSnapshot=function(){ const o=_sxSnap9o.apply(this,arguments); o.listening=sxListening(); o.talents=tlGet(); o.favs=fvShown(o.talents,(state.profile||{}).favs); return o; };
function sxListeningHtml(L){ const S=L.songs||[], A=L.artists||[]; if(!S.length&&!A.length) return `<p class="sx-none" data-testid="uprof-listening-empty">Nothing played yet.</p>`;
  return `${A.length?`<p class="sx-sub">Top artists</p><div class="sx-arts no-scrollbar" data-testid="uprof-top-artists">${A.map((a,i)=>{ const go=a.id&&ARTIST_BY_ID[a.id]; return `<button type="button" ${go?`data-act="artist-open" data-id="${esc(a.id)}"`:'disabled'} class="sx-art press" data-testid="uprof-top-artist-${i}"><span class="sx-art-img">${a.img?`<img src="${esc(a.img)}" alt="" loading="lazy">`:'<i data-lucide="mic-vocal"></i>'}<em class="font-doto">${i+1}</em></span><b class="clamp-1">${esc(a.n)}</b><small>${fmtNum(a.p||0)} play${a.p===1?'':'s'}</small></button>`; }).join('')}</div>`:''}
   ${S.length?`<p class="sx-sub">Most played</p><div data-testid="uprof-top-songs">${sxSongRows(S,'top',true)}</div>`:''}`; }
function sxFriendListHtml(F){ if(!F.length) return `<p class="sx-none" data-testid="uprof-friend-list-empty">No friends to show yet.</p>`;
  return `<div class="sx-list" data-testid="uprof-friend-list">${F.map((u,i)=>`<button type="button" data-act="sx-open" data-u="${esc(u.username)}" data-testid="uprof-friend-${esc(u.username)}" class="sx-row press" style="--d:${Math.min(i,8)*40}ms">${sxAv(u)}<span class="min-w-0 flex-1"><b class="sx-nm"><span class="clamp-1">${esc(u.display_name||u.username)}</span>${sxNameBadges(u,false,'fl-'+u.username)}</b><small class="clamp-1">@${esc(u.username)}</small></span><i data-lucide="chevron-right" class="sx-chev"></i></button>`).join('')}</div>`; }

/* my status: role, badges, ban, mute, staff edits */
async function stLoad(force){ if(!sb||!sbUser()){ state._sxMe=null; return null; } if(!force&&Date.now()-_stT<60000) return state._sxMe; _stT=Date.now();
  let d=null; try{ d=await sxRpc('my_status'); }catch(e){ return null; } const prev=JSON.stringify(state._sxMe||null); state._sxMe=d||null; if(d) await stApply(d);
  if(JSON.stringify(state._sxMe||null)!==prev){ pfRepaint(); try{ sbPaint(); if(state.view==='settings'&&state.settingsTab==='account') renderView(); }catch(e){} } return d; }
async function stApply(d){ if(d.banned_until&&Date.parse(d.banned_until)>Date.now()){ stBanned(d); return; }
  const rev=+d.mod_rev||0, seen=+(localStorage.getItem('sbx_mod_rev')||0), E=d.mod_edits;
  if(rev>seen&&E&&typeof E==='object'){ const p=Object.assign({},state.profile||{}), ch=[];
    if(E.display_name){ p.nickname=E.display_name; ch.push('name'); }
    if(E.username){ p.username=E.username; p.usernameSynced=E.username; ch.push('username'); }
    if('bio' in E){ p.bio=E.bio||''; ch.push('bio'); }
    if(E.remove_avatar){ p.avatar=''; p.avatarUrl=null; p.avatarSig=''; ch.push('photo'); }
    if(E.remove_banner){ try{ assetDel('profile_banner').catch(()=>{}); }catch(e){} state.profileBanner=''; sbMeta({bannerUrl:null,bannerSig:''}); ch.push('banner'); }
    state.profile=p; LS.set('treesh_profile',p); localStorage.setItem('sbx_mod_rev',String(rev)); try{ await sxRpc('ack_mod_edits',{rev}); }catch(e){}
    if(ch.length){ toast('A moderator updated your profile','Changed: '+ch.join(', ')); try{ renderShell(); renderSidebarLibrary(); }catch(e){} pfRepaint(); sbQueuePush(true); } }
  else if(rev>seen) localStorage.setItem('sbx_mod_rev',String(rev));
  if(!stMuted()){ if(localStorage.getItem('sbx_av_held')){ localStorage.removeItem('sbx_av_held'); if(state.profile){ state.profile.avatarSig=''; sbQuietSet('treesh_profile',state.profile); } sbQueuePush(true); }
    if(localStorage.getItem('sbx_bn_held')){ localStorage.removeItem('sbx_bn_held'); sbMeta({bannerSig:''}); sxPublishSoon(true); } } }
function stBanned(d){ $("#modal2").innerHTML=modal2Wrap(`<div class="mod-ban" data-testid="account-suspended-sheet"><div class="sba-hero"><span class="sba-orb is-err"><i data-lucide="ban"></i></span></div><h3 class="sba-mt">Your account is suspended</h3><p class="sba-md">You can\u2019t sign in ${esc(stUntil(d.banned_until))}.${d.ban_reason?`<br><b>Reason:</b> ${esc(d.ban_reason)}`:''}</p><div class="sba-col"><button type="button" data-act="modal2-close-ban" data-testid="account-suspended-ok" class="sba-btn is-primary lg press">OK</button><button type="button" data-act="ts-open" data-val="support" data-testid="account-suspended-support" class="sba-btn lg press"><i data-lucide="life-buoy"></i>Contact support</button></div><p class="sba-fine">Everything on this device stays here. You\u2019ve been signed out.</p></div>`,'account-suspended-modal');
  icons(); syncScrollLock(); state._sxMe=null; try{ sb.auth.signOut(); }catch(e){} }
const _sbSI9o=sbSignedIn; sbSignedIn=async function(u){ const r=await _sbSI9o.apply(this,arguments); setTimeout(()=>stLoad(true),300); return r; };
const _sbSO9o=sbSignedOut; sbSignedOut=function(){ state._sxMe=null; return _sbSO9o.apply(this,arguments); };
const _sbET9o=sbErrText; sbErrText=function(e){ const m=(e&&(e.message||e.error_description))||String(e||''); if(/banned/i.test(m)) return 'This account is suspended. Email support@treesh.app if you think it\u2019s a mistake.'; return _sbET9o.apply(this,arguments); };
const _sbAU9o=sbAvatarUpload; sbAvatarUpload=async function(uid,d){ if(stMuted()){ localStorage.setItem('sbx_av_held','1'); const p=state.profile||{}; if(p.avatarUrl&&/^https?:/.test(p.avatarUrl)) return p.avatarUrl; throw new Error('Photo saved on this device. It goes public when your mute ends.'); } return _sbAU9o.apply(this,arguments); };
const _opf9o=openProfile; openProfile=function(){ const r=_opf9o.apply(this,arguments); stLoad(false); return r; };

/* own profile: badges, talents, muted notice, staff button */
function modHeroBtn(){ return stStaff()?`<button type="button" data-act="mod-dash" data-testid="hero-mod-tools" class="sx-hbtn is-staff press"><i data-lucide="gavel"></i>Moderation</button>`:''; }
function stMuteNote(){ const m=stMe(); return stMuted()?`<div class="mod-note" data-testid="profile-muted-note"><i data-lucide="volume-x"></i><span><b>You\u2019re muted ${esc(stUntil(m.muted_until))}.</b> You can keep editing. Changes stay private until the mute ends.${m.mute_reason?' Reason: '+esc(m.mute_reason):''}</span></div>`:''; }
const _sph9o=settingsProfileHtml; settingsProfileHtml=function(editing){ let h=_sph9o.apply(this,arguments);
  if(editing){ h=h.replace('<div class="mt-4 grid gap-4 sm:grid-cols-2">',stMuteNote()+'<div class="mt-4 grid gap-4 sm:grid-cols-2">'); const blk=tlEditHtml(); const a='<div class="mt-6"><section class="pfa-card"', b='<div class="mt-4 flex items-center gap-2"><button data-act="save-profile"'; const i=h.indexOf(a)>=0?h.indexOf(a):h.indexOf(b); return i<0?h:h.slice(0,i)+blk+h.slice(i); }
  const me=stMe(); if(me) h=h.replace(/(data-testid="settings-profile-name">)([^<]*)<\/h1>/,(m,a,n)=>a+n+sxNameBadges(me,true,'me')+'</h1>');
  const t=tlGet(), nf=fvCount(fvShown(t,(state.profile||{}).favs)), row=`<div class="tl-row">${t?tlBadge(t,'me','profile-talent-badge'):`<button type="button" data-act="tl-pick" data-testid="profile-add-talents" class="tl-add press"><i data-lucide="plus"></i>Add talents</button>`}${nf?`<button type="button" data-act="tl-view" data-val="me" data-testid="profile-favorites-badge" class="tl-fav press"><i data-lucide="heart"></i>${nf} favorite${nf===1?'':'s'}</button>`:''}${stMuted()?`<span class="sx-chip is-warn" data-testid="profile-muted-chip"><i data-lucide="volume-x"></i>Muted</span>`:''}</div>`;
  return h.replace(/(data-testid="settings-profile-name">[\s\S]*?<\/h1>(?:<p class="pf-uname"[^>]*>[^<]*<\/p>)?)/,(m,a)=>a+row); };
const _sac9o=sbAccountCardHtml; sbAccountCardHtml=function(tab){ const h=_sac9o.apply(this,arguments); if(!h||!stStaff()) return h;
  return h+`<section class="sba-card mod-card" data-testid="mod-settings-card"><div class="sba-head"><span class="sba-ic"><i data-lucide="gavel"></i></span><div class="min-w-0 flex-1"><h2 class="sba-t">Moderation</h2><p class="sba-s">You\u2019re a Treesh ${stRole()==='admin'?'admin':'moderator'}. See bans, mutes, staff and the action log.</p></div></div><div class="sba-acts"><button type="button" data-act="mod-dash" data-testid="mod-open-dashboard" class="sba-btn is-primary press"><i data-lucide="gavel"></i>Open moderation</button></div></section>`; };

/* moderation sheet for one person */
function modCan(a){ const d=_sxV&&_sxV.d, vr=d&&d.mod&&d.mod.viewer_role; if(!vr||vr==='user') return false; const adm=vr==='admin';
  if(d.role==='admin'&&!adm) return false; if(a==='ban'||a==='verify') return adm; if(a==='role') return adm; if(a==='delete') return adm&&d.role!=='admin'; return true; }
function modOpen(){ const d=_sxV&&_sxV.d; if(!d||!d.mod) return; _mod={tab:'status',banDur:'1d',muteDur:'1d',busy:false}; modPaint(true); }
function modPaint(fresh){ const html=`<div class="mod-sheet" data-testid="moderation-sheet">${modHtml()}</div>`; const s=document.querySelector('#modal2 .mod-sheet');
  if(s&&!fresh){ const y=(s.querySelector('.mod-body')||{}).scrollTop||0; s.outerHTML=html; const b=document.querySelector('#modal2 .mod-body'); if(b) b.scrollTop=y; } else $("#modal2").innerHTML=modal2Wrap(html,'moderation-modal','xl'); icons(); syncScrollLock(); }
function modDurHtml(k){ const cur=_mod[k+'Dur']; const now=new Date(Date.now()+36e5-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,16);
  return `<div class="tsf-chips mod-durs" data-testid="mod-${k}-durations">${MOD_DUR.map(([id,l])=>`<button type="button" data-act="mod-dur" data-k="${k}" data-val="${id}" aria-pressed="${cur===id}" data-testid="mod-${k}-dur-${id}" class="tsf-chip press${cur===id?' on':''}">${l}</button>`).join('')}</div>
   ${cur==='custom'?`<label class="sba-f mt-3"><span>Until</span><input type="datetime-local" id="mod-${k}-until" min="${now}" value="${now}" class="tsf-sel" data-testid="mod-${k}-until"></label>`:''}
   <label class="sba-f mt-3"><span>Reason <i class="tsf-opt">${k==='ban'?'shown to them':'optional'}</i></span><input id="mod-${k}-reason" maxlength="300" placeholder="${k==='ban'?'e.g. Harassing other users':'e.g. Inappropriate bio'}" data-testid="mod-${k}-reason"></label>`; }
