function fvTlKeys(t){ t=tlNorm(t); if(!t) return []; const out=[]; [t.main].concat(t.more).forEach(id=>{ const k=FV_BY_TL[id]||FV_BY_CAT[TL_BY[id].c]; if(k&&!out.includes(k)) out.push(k); }); return out; }
function fvKeys(t){ const out=fvTlKeys(t); FV_GENERAL.forEach(k=>{ if(!out.includes(k)) out.push(k); }); return out; }
function fvClean(f){ const o={}; if(!f||typeof f!=='object') return o; Object.keys(FV_LISTS).forEach(k=>{ const L=FV_LISTS[k][2]; const v=(Array.isArray(f[k])?f[k]:[]).filter((x,i,a)=>L.includes(x)&&a.indexOf(x)===i).slice(0,FV_MAX); if(v.length) o[k]=v; }); return o; }
function fvShown(t,f){ const c=fvClean(f), o={}; fvKeys(t).forEach(k=>{ if(c[k]) o[k]=c[k]; }); return o; }
function fvCount(F){ return Object.values(F||{}).reduce((n,a)=>n+a.length,0); }
function fvHtml(F){ return Object.keys(F).map(k=>`<section class="fv-sec" data-testid="favorites-view-${k}"><p class="tsf-k"><i data-lucide="${FV_LISTS[k][1]}"></i>${esc(FV_LISTS[k][0])}</p><div class="tl-chips">${F[k].map(x=>`<span class="fv-chip">${esc(x)}</span>`).join('')}</div></section>`).join(''); }
const TL_BY={}; TL_CATS.forEach(([c,l])=>l.forEach(t=>{ TL_BY[t[0]]={id:t[0],l:t[1],ic:t[2],c}; }));
function tlNorm(t){ if(!t||typeof t!=='object') return null; const main=TL_BY[t.main]?t.main:''; const more=(Array.isArray(t.more)?t.more:[]).filter((x,i,a)=>TL_BY[x]&&x!==main&&a.indexOf(x)===i).slice(0,TL_MAX); if(!main&&!more.length) return null; return main?{main,more}:{main:more[0],more:more.slice(1)}; }
function tlGet(){ return tlNorm((state.profile||{}).talents); }
function tlBadge(t,who,tid){ t=tlNorm(t); if(!t) return ''; const m=TL_BY[t.main], n=t.more.length; return `<button type="button" data-act="tl-view" data-val="${who}" data-testid="${tid}" class="tl-badge press" aria-label="${esc(m.l)}${n?', plus '+n+' more talents':''}. See all talents"><i data-lucide="${m.ic}"></i><span>${esc(m.l)}</span>${n?`<em>+${n}</em>`:''}</button>`; }
function tlEditHtml(){ const t=tlGet(); return `<div class="mt-5 tl-edit" data-testid="profile-talents-edit"><label class="mb-1.5 block text-xs uppercase tracking-wide text-white/50">Talents</label><div class="tl-edit-row">${t?[t.main].concat(t.more).map((id,i)=>`<span class="tl-chip${i?'':' is-main'}"><i data-lucide="${TL_BY[id].ic}"></i>${esc(TL_BY[id].l)}${i?'':'<span class="tl-star"><i data-lucide="star"></i></span>'}</span>`).join(''):'<span class="tl-hint">Show people what you do. Pick a main talent, then add more.</span>'}<button type="button" data-act="tl-pick" data-testid="profile-talents-choose" class="tl-add press"><i data-lucide="${t?'pencil':'plus'}"></i>${t?'Edit talents':'Add talents'}</button></div>${(()=>{ const nf=fvCount(fvShown(t,(state.profile||{}).favs)); return `<p class="tl-sub">${nf?nf+' favorite'+(nf===1?'':'s')+' picked. ':''}<button type="button" data-act="tl-pick" data-val="favs" data-testid="profile-favorites-choose" class="tl-link press">${nf?'Edit favorites':'Add favorite '+esc(fvKeys(t).map(k=>FV_LISTS[k][0].toLowerCase()).slice(0,2).join(' & '))}</button></p>`; })()}</div>`; }
function tlViewOpen(who){ const them=who==='them'; const src=them?((_sxV&&_sxV.d&&_sxV.d.data)||{}):(state.profile||{}); const t=tlNorm(src.talents), F=fvShown(t,src.favs); if(!t&&!fvCount(F)) return;
  const nm=them?(_sxV.d.display_name||_sxV.d.username):'Your', m=t?TL_BY[t.main]:null, nf=fvCount(F);
  $("#modal2").innerHTML=modal2Wrap(`<div class="tl-view" data-testid="talents-view-sheet"><div class="tsf-head"><span class="sba-orb"><i data-lucide="${t?'sparkles':'heart'}"></i></span><div class="min-w-0 flex-1"><h3 class="tsf-t">${them?esc(nm)+'\u2019s '+(t?'talents':'favorites'):'Your '+(t?'talents':'favorites')}</h3><p class="tsf-d">${t?(1+t.more.length)+' talent'+(t.more.length?'s':''):''}${t&&nf?' \u00b7 ':''}${nf?nf+' favorite'+(nf===1?'':'s'):''}</p></div><button type="button" data-act="modal2-close" aria-label="Close" data-testid="talents-view-close" class="tsf-x press"><i data-lucide="x"></i></button></div>
   ${m?`<div class="tl-main" data-testid="talents-view-main"><span class="tl-main-ic"><i data-lucide="${m.ic}"></i></span><span class="min-w-0"><small><i data-lucide="star"></i>Main talent</small><b>${esc(m.l)}</b><em>${esc(m.c)}</em></span></div>`:''}
   ${t&&t.more.length?`<p class="tsf-k mt-5">Also</p><div class="tl-grid" data-testid="talents-view-list">${t.more.map((id,i)=>`<div class="tl-cell" style="--d:${i*35}ms" data-testid="talents-view-${id}"><span class="tl-cell-ic"><i data-lucide="${TL_BY[id].ic}"></i></span><span class="min-w-0"><b class="clamp-1">${esc(TL_BY[id].l)}</b><small>${esc(TL_BY[id].c)}</small></span></div>`).join('')}</div>`:''}
   ${fvCount(F)?`<div class="fv-view" data-testid="favorites-view"><p class="tl-h"><i data-lucide="heart"></i>Favorites</p>${fvHtml(F)}</div>`:''}
   ${them?'':`<div class="mod-row mt-6"><button type="button" data-act="tl-pick" data-testid="talents-view-edit" class="sba-btn lg press"><i data-lucide="pencil"></i>Edit talents</button><button type="button" data-act="tl-pick" data-val="favs" data-testid="favorites-view-edit" class="sba-btn lg press"><i data-lucide="heart"></i>Edit favorites</button></div>`}</div>`,'talents-view-modal','lg'); icons(); syncScrollLock(); }
let _tl=null;
function tlPickOpen(tab){ const t=tlGet(); _tl={main:t?t.main:'',more:t?t.more.slice():[],q:'',tab:tab==='favs'?'favs':'talents',favs:fvClean((state.profile||{}).favs)};
  $("#modal2").innerHTML=modal2Wrap(`<div class="tl-pick" data-testid="talents-picker"><div class="tsf-head"><span class="sba-orb"><i data-lucide="sparkles"></i></span><div class="min-w-0 flex-1"><h3 class="tsf-t">Talents &amp; favorites</h3><p class="tsf-d">Your first talent is your main one. Add up to ${TL_MAX} more.</p></div><button type="button" data-act="modal2-close" aria-label="Close" data-testid="talents-close" class="tsf-x press"><i data-lucide="x"></i></button></div>
   <div class="sx-tabs no-scrollbar tl-tabs" role="tablist" data-testid="talents-tabs"><button type="button" role="tab" data-act="tl-tab" data-val="talents" data-testid="talents-tab-talents" class="sx-tab${_tl.tab==='talents'?' on':''}"><i data-lucide="sparkles"></i>Talents</button><button type="button" role="tab" data-act="tl-tab" data-val="favs" data-testid="talents-tab-favorites" class="sx-tab${_tl.tab==='favs'?' on':''}"><i data-lucide="heart"></i>Favorites</button></div>
   <div class="tl-sel" id="tl-sel" data-testid="talents-selected">${tlSelHtml()}</div>
   <label class="tl-search"><i data-lucide="search"></i><input id="tl-q" autocomplete="off" placeholder="${_tl.tab==='favs'?'Search favorites':'Search '+Object.keys(TL_BY).length+' talents'}" data-testid="talents-search"></label>
   <div class="tl-list soft-scroll" id="tl-list" data-testid="talents-list">${tlListHtml()}</div>
   <div class="tl-foot"><button type="button" data-act="tl-save" data-testid="talents-save" class="sba-btn is-primary lg press"><i data-lucide="check"></i>Save</button></div></div>`,'talents-modal','xl'); icons(); syncScrollLock(); }
function tlSelHtml(){ if(_tl.tab==='favs'){ const n=fvCount(fvShown({main:_tl.main,more:_tl.more},_tl.favs)); return `<p class="tl-hint" data-testid="favorites-hint">Pick up to ${FV_MAX} in each list. ${_tl.main?'Your talents unlock extra lists.':'Add talents to unlock more lists.'}${n?` <b>${n} picked</b>`:''}</p>`; }
  if(!_tl.main) return `<p class="tl-hint" data-testid="talents-empty">Tap a talent below to make it your main one.</p>`;
  const chip=(id,main)=>`<span class="tl-chip${main?' is-main':''}" data-testid="talents-selected-${id}"><i data-lucide="${TL_BY[id].ic}"></i>${esc(TL_BY[id].l)}${main?'<span class="tl-star"><i data-lucide="star"></i>Main</span>':`<button type="button" data-act="tl-main" data-val="${id}" aria-label="Make ${esc(TL_BY[id].l)} your main talent" title="Make main" data-testid="talents-make-main-${id}"><i data-lucide="star"></i></button>`}<button type="button" data-act="tl-rm" data-val="${id}" aria-label="Remove ${esc(TL_BY[id].l)}" data-testid="talents-remove-${id}"><i data-lucide="x"></i></button></span>`;
  return chip(_tl.main,true)+_tl.more.map(id=>chip(id,false)).join('')+`<span class="tl-count" data-testid="talents-count">${_tl.more.length}/${TL_MAX} more</span>`; }
function tlListHtml(){ const q=_tl.q.trim().toLowerCase(); let h='';
  if(_tl.tab==='favs'){ const tt={main:_tl.main,more:_tl.more}, keys=fvKeys(tt), tk=fvTlKeys(tt);
    keys.forEach(k=>{ const [title,ic,L]=FV_LISTS[k], cur=_tl.favs[k]||[]; const items=L.filter(x=>!q||x.toLowerCase().includes(q)||title.toLowerCase().includes(q)); if(!items.length) return;
      h+=`<section class="tl-cat" data-testid="favorites-list-${k}"><p class="tsf-k"><i data-lucide="${ic}"></i>${esc(title)}${tk.includes(k)&&!FV_GENERAL.includes(k)?'<span class="fv-tag" data-testid="favorites-tag-'+k+'">From your talents</span>':''}<span class="tl-n">${cur.length}/${FV_MAX}</span></p><div class="tl-chips">${items.map((x,i)=>{ const on=cur.includes(x); return `<button type="button" data-act="fv-tog" data-k="${k}" data-val="${esc(x)}" aria-pressed="${on}" data-testid="favorite-opt-${k}-${L.indexOf(x)}" class="tl-opt press${on?' on':''}">${on?'<i data-lucide="check"></i>':''}${esc(x)}</button>`; }).join('')}</div></section>`; });
    return h||`<p class="sx-none">Nothing matches \u201c${esc(q)}\u201d.</p>`; }
  TL_CATS.forEach(([c,l])=>{ const items=l.filter(t=>!q||t[1].toLowerCase().includes(q)||c.toLowerCase().includes(q)); if(!items.length) return;
    h+=`<section class="tl-cat"><p class="tsf-k">${esc(c)}</p><div class="tl-chips">${items.map(t=>{ const on=_tl.main===t[0]||_tl.more.includes(t[0]); return `<button type="button" data-act="tl-tog" data-val="${t[0]}" aria-pressed="${on}" data-testid="talent-opt-${t[0]}" class="tl-opt press${on?' on':''}${_tl.main===t[0]?' is-main':''}"><i data-lucide="${t[2]}"></i>${esc(t[1])}</button>`; }).join('')}</div></section>`; });
  return h||`<p class="sx-none">No talents match \u201c${esc(q)}\u201d.</p>`; }
function tlPaint(list){ const s=document.getElementById('tl-sel'); if(s) s.innerHTML=tlSelHtml(); if(list!==false){ const l=document.getElementById('tl-list'); if(l){ const y=l.scrollTop; l.innerHTML=tlListHtml(); l.scrollTop=y; } } icons(); }
function tlSave(){ const p=Object.assign({},state.profile||{}); p.talents=_tl.main?{main:_tl.main,more:_tl.more.slice()}:null; p.favs=fvClean(_tl.favs); if(state.settingsEditProfile) pfStashDraft(); state.profile=p; LS.set('treesh_profile',p); closeModal2(); _tl=null; const nf=fvCount(fvShown(p.talents,p.favs)); toast(p.talents?'Talents saved':nf?'Favorites saved':'Talents cleared',p.talents?TL_BY[p.talents.main].l+(p.talents.more.length?' + '+p.talents.more.length+' more':''):nf?nf+' picked':''); pfRepaint(); try{ sxPublishSoon(); }catch(e){} }
document.addEventListener('input',e=>{ if(!e.target||e.target.id!=='tl-q'||!_tl) return; _tl.q=e.target.value; tlPaint(); });

document.addEventListener('click',e=>{ const t=e.target&&e.target.closest&&e.target.closest('[data-act]'); if(!t) return; const a=t.dataset.act, v=t.dataset.val;
  if(a.indexOf('tl-')===0){ switch(a){
    case 'tl-view': tlViewOpen(v); break;
    case 'tl-pick': tlPickOpen(v); break;
    case 'tl-tab': if(!_tl) break; _tl.tab=v==='favs'?'favs':'talents'; _tl.q=''; document.querySelectorAll('#modal2 [data-act="tl-tab"]').forEach(b=>b.classList.toggle('on',b.dataset.val===_tl.tab)); { const i=document.getElementById('tl-q'); if(i){ i.value=''; i.placeholder=_tl.tab==='favs'?'Search favorites':'Search '+Object.keys(TL_BY).length+' talents'; } } tlPaint(); { const l=document.getElementById('tl-list'); if(l) l.scrollTop=0; } break;
    case 'tl-save': if(_tl) tlSave(); break;
    case 'tl-tog': if(!_tl) break; if(_tl.main===v){ _tl.main=_tl.more.shift()||''; } else if(_tl.more.includes(v)) _tl.more.splice(_tl.more.indexOf(v),1); else if(!_tl.main) _tl.main=v; else if(_tl.more.length>=TL_MAX){ toast('That\u2019s the max','Remove one to add another'); break; } else _tl.more.push(v); tlPaint(); break;
    case 'tl-rm': if(!_tl) break; if(_tl.main===v) _tl.main=_tl.more.shift()||''; else _tl.more=_tl.more.filter(x=>x!==v); tlPaint(); break;
    case 'tl-main': if(!_tl||!_tl.more.includes(v)) break; _tl.more=_tl.more.filter(x=>x!==v); if(_tl.main) _tl.more.unshift(_tl.main); _tl.main=v; tlPaint(); break; } return; }
  if(a==='fv-tog'){ if(!_tl) return; const k=t.dataset.k, cur=(_tl.favs[k]=_tl.favs[k]||[]); const i=cur.indexOf(v); if(i>=0) cur.splice(i,1); else if(cur.length>=FV_MAX){ toast('That\u2019s the max for this list','Remove one to add another'); return; } else cur.push(v); tlPaint(); return; }
  if(a==='modal2-close-ban'){ closeModal2(); return; }
  if(a==='mod-dash'){ modDashOpen(); return; }
  if(a==='mod-open-u'){ const u=t.dataset.u; if(!u) return; closeModal2(); _modD=null; sxOpenProfile(u); return; }
  if(a==='mod-dtab'){ if(!_modD) return; _modD.tab=v; _modD.list=null; _modD.q=''; const i=document.getElementById('mod-q'); if(i) i.value=''; modDashLoad(); return; }
  if(a==='modal2-close'&&t.closest('.mod-sheet,.tl-pick,.tl-view')){ closeModal2(); _mod=null; _modD=null; _tl=null; return; }
  if(a==='mod-open'){ modOpen(); return; }
  if(!_mod||!t.closest('.mod-sheet')) return;
  if(a==='mod-tab'){ _mod.tab=v; _mod.ask=null; modPaint(); return; }
  if(a==='mod-ask-no'){ _mod.ask=null; modPaint(); return; }
  if(a==='mod-ask-yes'){ const A=_mod.ask; _mod.ask=null; if(A) A.fn(); return; }
  if(a==='mod-dur'){ _mod[t.dataset.k+'Dur']=v; const r=document.getElementById('mod-'+t.dataset.k+'-reason'), rv=r?r.value:''; modPaint(); const r2=document.getElementById('mod-'+t.dataset.k+'-reason'); if(r2) r2.value=rv; return; }
  if(a.indexOf('mod-')===0) modAct(a,t); });
